function col(n){let s='';while(n){let m=(n-1)%26;s=String.fromCharCode(65+m)+s;n=(n-m-1)/26|0;}return s;}
const sh = ss.getSheetByName('Income Statement');
const cols = [8,9,10,11,12]; // H:L
const letters = cols.map(col);
const prevLetters = ['G','H','I','J','K'];

function setRow(row, formulas){
  sh.getRange(row,8,1,5).setFormulas([formulas]);
}
function byCol(fn){ return letters.map((c,i)=>fn(c, prevLetters[i], i)); }

